  assert.deepEqual(sucessos, [7]);
  assert.deepEqual(erros, []);
});

test('chama o callback de sucesso também com zero', async () => {
  const sucessos = [];
  const erros = [];
  await processarNumero(0, (v) => sucessos.push(v), (e) => erros.push(e));
  assert.deepEqual(sucessos, [0]);
  assert.deepEqual(erros, []);
});

test('chama o callback de erro quando o valor não é número', async () => {
  const sucessos = [];
  const erros = [];
  await processarNumero('abc', (v) => sucessos.push(v), (e) => erros.push(e));
  assert.deepEqual(sucessos, []);
  assert.equal(erros.length, 1);
});

test('chama o callback de erro com a mensagem certa', async () => {
  const sucessos = [];
  const erros = [];
  await processarNumero(null, (v) => sucessos.push(v), (e) => erros.push(e.message));
  assert.deepEqual(sucessos, []);
  assert.deepEqual(erros, ['valor não é número']);
});

solutionCode:
export async function processarNumero(valor, aoSucesso, aoErro) {
  if (typeof valor !== 'number') {
    aoErro(new Error('valor não é número'));
    return;
  }
  aoSucesso(valor);
}
